26	/*--------------------------------- Basics ---------------------------------*/
27	
28	typedef enum { sox_false, sox_true } sox_bool;
29	
30	typedef int32_t  sox_int32_t;
31	typedef uint32_t sox_uint32_t;
32	typedef int64_t  sox_int64_t;
33	typedef uint64_t sox_uint64_t;
34	
35	typedef int32_t sox_sample_t;
36	
37	#define SOX_SAMPLE_PRECISION 32
38	#define SOX_SAMPLE_MAX ((sox_sample_t)2147483647L)
39	#define SOX_SAMPLE_MIN ((sox_sample_t)(-2147483647L - 1L))
40	#define SOX_SAMPLE_NEG SOX_SAMPLE_MIN
41	#define SOX_UNSPEC 0
42	#define SOX_IGNORE_LENGTH ((sox_uint64_t)(-1))
43	#define SOX_UNKNOWN_LEN ((sox_uint64_t)(-1))
44	
45	#define SOX_SUCCESS 0
46	#define SOX_EOF (-1)
47	#define SOX_EHDR 2000
48	#define SOX_EFMT 2001
49	#define SOX_ENOMEM 2002
50	#define SOX_EPERM 2003
51	#define SOX_ENOTSUP 2004
52	#define SOX_EINVAL 2005
53	
54	#define SOX_MAX_NLOOPS 8
55	
56	/*----------------------- Sample conversion machinery -----------------------*/
57	
58	extern sox_sample_t lsx_macro_temp_sample;
59	extern double lsx_macro_temp_double;
60	
61	#define SOX_INT_MIN(bits) (1 << ((bits) - 1) == 0 ? INT_MIN : \
62	                           -(1 << ((bits) - 1)))
63	#define SOX_INT_MAX(bits) (int)(((unsigned)-1) >> (33 - (bits)))
64	#define SOX_UINT_MAX(bits) (int)(SOX_INT_MIN(bits) ^ SOX_INT_MAX(bits))
65	
66	#define SOX_INT_TO_SAMPLE(d, bits) ((sox_sample_t)(d) << (32 - (bits)))
67	#define SOX_UINT_TO_SAMPLE(d, bits) \
68	    ((sox_sample_t)((((unsigned)(d)) ^ (unsigned)SOX_INT_MIN(bits)) << (32 - (bits))))
69	
70	/* Round-to-nearest with saturation towards SOX_INT_MAX. */
71	#define SOX_SAMPLE_TO_SIGNED(bits, d, clips) \
72	    (int32_t)( \
73	      lsx_macro_temp_sample = (d), \
74	      lsx_macro_temp_sample > (sox_sample_t)(SOX_SAMPLE_MAX - (1 << (31 - (bits)))) ? \
75	        ++(clips), SOX_INT_MAX(bits) : \
76	        ((uint32_t)(lsx_macro_temp_sample + (1 << (31 - (bits))))) >> (32 - (bits)))
77	
78	#define SOX_SAMPLE_TO_UNSIGNED(bits, d, clips) \
79	    (uint32_t)(SOX_SAMPLE_TO_SIGNED(bits, d, clips) ^ SOX_INT_MIN(bits))
80	
81	#define SOX_SIGNED_8BIT_TO_SAMPLE(d, c)   SOX_INT_TO_SAMPLE(d, 8)
82	#define SOX_UNSIGNED_8BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 8)
83	#define SOX_SIGNED_16BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 16)
84	#define SOX_UNSIGNED_16BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 16)
85	#define SOX_SIGNED_24BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 24)
86	#define SOX_UNSIGNED_24BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 24)
87	#define SOX_SIGNED_32BIT_TO_SAMPLE(d, c)  ((sox_sample_t)(d))
88	#define SOX_UNSIGNED_32BIT_TO_SAMPLE(d, c) \
89	    ((sox_sample_t)((d) ^ (uint32_t)0x80000000UL))
90	
91	#define SOX_SAMPLE_TO_SIGNED_8BIT(d, c)    (int8_t)SOX_SAMPLE_TO_SIGNED(8, d, c)
92	#define SOX_SAMPLE_TO_UNSIGNED_8BIT(d, c)  (uint8_t)SOX_SAMPLE_TO_UNSIGNED(8, d, c)
93	#define SOX_SAMPLE_TO_SIGNED_16BIT(d, c)   (int16_t)SOX_SAMPLE_TO_SIGNED(16, d, c)
94	#define SOX_SAMPLE_TO_UNSIGNED_16BIT(d, c) (uint16_t)SOX_SAMPLE_TO_UNSIGNED(16, d, c)
95	#define SOX_SAMPLE_TO_SIGNED_24BIT(d, c)   (int32_t)SOX_SAMPLE_TO_SIGNED(24, d, c)
96	#define SOX_SAMPLE_TO_UNSIGNED_24BIT(d, c) (uint32_t)SOX_SAMPLE_TO_UNSIGNED(24, d, c)
97	#define SOX_SAMPLE_TO_SIGNED_32BIT(d, c)   ((int32_t)(d))
98	#define SOX_SAMPLE_TO_UNSIGNED_32BIT(d, c) \
99	    (uint32_t)((d) ^ (sox_sample_t)SOX_SAMPLE_MIN)
100	
101	/* Floating point <-> sample.  Full-scale is +/- 1.0 mapped onto 2^31. */
102	#define SOX_FLOAT_32BIT_TO_SAMPLE(d, clips) \
103	    (sox_sample_t)(LSX_UNUSED_VAR(lsx_macro_temp_sample), \
104	      lsx_macro_temp_double = (d) * (SOX_SAMPLE_MAX + 1.0), \
105	      lsx_macro_temp_double < SOX_SAMPLE_MIN * 1.0 ? \
106	        ++(clips), SOX_SAMPLE_MIN : \
107	      lsx_macro_temp_double >= SOX_SAMPLE_MAX + 1.0 ? \
108	        lsx_macro_temp_double > SOX_SAMPLE_MAX + 1.0 ? \
109	          ++(clips), SOX_SAMPLE_MAX : SOX_SAMPLE_MAX : \
110	        (sox_sample_t)lsx_macro_temp_double)
111	#define SOX_FLOAT_64BIT_TO_SAMPLE(d, clips) SOX_FLOAT_32BIT_TO_SAMPLE(d, clips)
112	
113	#define SOX_SAMPLE_TO_FLOAT_32BIT(d, clips) \
114	    (float)(LSX_UNUSED_VAR(lsx_macro_temp_double), \
115	      lsx_macro_temp_sample = (d), \
116	      lsx_macro_temp_sample > SOX_SAMPLE_MAX - 64 ? \
117	        ++(clips), (SOX_SAMPLE_MAX - 64) * (1.0 / (SOX_SAMPLE_MAX + 1.0)) : \
118	        lsx_macro_temp_sample * (1.0 / (SOX_SAMPLE_MAX + 1.0)))
119	#define SOX_SAMPLE_TO_FLOAT_64BIT(d, clips) \
120	    ((double)(d) * (1.0 / (SOX_SAMPLE_MAX + 1.0)))
121	
122	#define SOX_SAMPLE_CLIP_COUNT(samp, clips) do { \
123	    if ((samp) > SOX_SAMPLE_MAX) { (samp) = SOX_SAMPLE_MAX; ++(clips); } \
124	    else if ((samp) < SOX_SAMPLE_MIN) { (samp) = SOX_SAMPLE_MIN; ++(clips); } \
125	  } while (0)
126	
127	#define SOX_ROUND_CLIP_COUNT(d, clips) \
128	    ((d) < 0 ? (d) <= SOX_SAMPLE_MIN - 0.5 ? ++(clips), SOX_SAMPLE_MIN \
129	                                           : (d) - 0.5 \
130	             : (d) >= SOX_SAMPLE_MAX + 0.5 ? ++(clips), SOX_SAMPLE_MAX \
131	                                           : (d) + 0.5)
132	
133	#define SOX_INTEGER_CLIP_COUNT(type, d, clips) \
134	    ((d) < 0 ? (d) <= type##_MIN ? ++(clips), type##_MIN : (d) \
135	             : (d) >= type##_MAX ? ++(clips), type##_MAX : (d))
136	#define SOX_16BIT_CLIP_COUNT(d, clips) SOX_INTEGER_CLIP_COUNT(INT16, d, clips)
137	#define SOX_24BIT_CLIP_COUNT(d, clips) \
138	    ((d) < 0 ? (d) <= -8388609 ? ++(clips), -8388608 : (d) \
139	             : (d) >= 8388608 ? ++(clips), 8388607 : (d))
140	
