/* Low-level file I/O helpers shared by every format module.
 *
 * Original work; the behaviour reproduced here (in particular the wording of
 * the "overriding ..." diagnostics) was determined by running the reference
 * program.  See ../notes/formats_i.md.
 *
 * All multi-byte accessors honour ft->encoding.reverse_bytes, which is
 * SOX_OPTION_YES when the on-disk byte order is the opposite of the host's.
 * The host this is built for is little-endian, but the code below only ever
 * reverses bytes relative to the host, so it stays correct either way.
 */
#include "sox_i.h"
#include <inttypes.h>
#include <stdarg.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define reversing(ft) ((ft)->encoding.reverse_bytes == SOX_OPTION_YES)

/*-------------------------------- utilities --------------------------------*/

static int io_fail(sox_format_t ft, int err, char const *fmt, ...)
{
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(ft->sox_errstr, sizeof(ft->sox_errstr), fmt, ap);
  va_end(ap);
  ft->sox_errno = err;
  return SOX_EOF;
}

/* Reverse the bytes of each of `n' items of `size' bytes, in place. */
static void reverse_items(void *p, size_t size, size_t n)
{
  unsigned char *q = p;
  size_t i, j, half = size / 2;

  for (i = 0; i < n; ++i, q += size)
    for (j = 0; j < half; ++j) {
      unsigned char t = q[j];
      q[j] = q[size - 1 - j];
      q[size - 1 - j] = t;
    }
}

static uint16_t swap16(uint16_t x)
{
  return (uint16_t)((x >> 8) | (x << 8));
}

static uint32_t swap32(uint32_t x)
{
  return ((x & 0x000000ffu) << 24) | ((x & 0x0000ff00u) <<  8) |
         ((x & 0x00ff0000u) >>  8) | ((x & 0xff000000u) >> 24);
}

static uint64_t swap64(uint64_t x)
{
  return ((uint64_t)swap32((uint32_t)x) << 32) | swap32((uint32_t)(x >> 32));
}

/*---------------------------- raw buffered i/o -----------------------------*/

size_t lsx_readbuf(sox_format_t ft, void *buf, size_t len)
{
  size_t got;

  if (!ft->fp || !len)
    return 0;
  got = fread(buf, (size_t)1, len, ft->fp);
  ft->tell_off += (off_t)got;
  ft->tell_off_valid = sox_true;
  if (got != len) {
    ft->eof = sox_true;
    if (ferror(ft->fp))
      io_fail(ft, errno, "error reading `%s': %s",
              ft->filename ? ft->filename : "", strerror(errno));
  }
  return got;
}

size_t lsx_writebuf(sox_format_t ft, void const *buf, size_t len)
{
  size_t put;

  if (!ft->fp || !len)
    return 0;
  put = fwrite(buf, (size_t)1, len, ft->fp);
  ft->tell_off += (off_t)put;
  ft->tell_off_valid = sox_true;
  if (put != len) {
    ft->eof = sox_true;
    io_fail(ft, errno, "error writing `%s': %s",
            ft->filename ? ft->filename : "", strerror(errno));
  }
  return put;
}

int lsx_eof(sox_format_t ft)
{
  if (ft->eof)
    return 1;
  return ft->fp && feof(ft->fp) ? 1 : 0;
}

int lsx_error(sox_format_t ft)
{
  return ft->fp ? ferror(ft->fp) : 0;
}

int lsx_flush(sox_format_t ft)
{
  return ft->fp ? fflush(ft->fp) : 0;
}

void lsx_clearerr(sox_format_t ft)
{
  if (ft->fp)
    clearerr(ft->fp);
  ft->eof = sox_false;
}

void lsx_rewind(sox_format_t ft)
{
  if (ft->fp)
    rewind(ft->fp);
  ft->tell_off = 0;
  ft->tell_off_valid = sox_true;
  ft->eof = sox_false;
}

off_t lsx_tell(sox_format_t ft)
{
  if (ft->fp && ft->seekable) {
    off_t where = ftello(ft->fp);
    if (where >= 0)
      return where;
  }
  return ft->tell_off;
}

int lsx_unreadb(sox_format_t ft, unsigned b)
{
  if (!ft->fp || ungetc((int)(b & 0xff), ft->fp) == EOF)
    return SOX_EOF;
  ft->tell_off -= 1;
  ft->eof = sox_false;
  return SOX_SUCCESS;
}

/* Consume and throw away `n' bytes; used when a stream cannot be seeked. */
static int discard_bytes(sox_format_t ft, uint64_t n)
{
  char trash[1024];

  while (n) {
    size_t want = n > sizeof(trash) ? sizeof(trash) : (size_t)n;
    size_t got = lsx_readbuf(ft, trash, want);
    if (!got)
      return SOX_EOF;
    n -= got;
  }
  return SOX_SUCCESS;
}

int lsx_seeki(sox_format_t ft, off_t offset, int whence)
{
  if (!ft->fp)
    return io_fail(ft, SOX_EOF, "no file to seek in");

  if (!ft->seekable) {
    /* Seeking forwards in a stream can be emulated by reading. */
    if (whence == SEEK_CUR && offset >= 0) {
      if (discard_bytes(ft, (uint64_t)offset) != SOX_SUCCESS)
        return io_fail(ft, SOX_EOF, "`%s': offset past EOF",
                       ft->filename ? ft->filename : "");
      ft->sox_errno = SOX_SUCCESS;
      return SOX_SUCCESS;
    }
    return io_fail(ft, SOX_EOF, "`%s': file is not seekable",
                   ft->filename ? ft->filename : "");
  }

  if (fseeko(ft->fp, offset, whence) < 0)
    return io_fail(ft, errno, "`%s': %s", ft->filename ? ft->filename : "",
                   strerror(errno));

  ft->tell_off = ftello(ft->fp);
  ft->tell_off_valid = sox_true;
  ft->eof = sox_false;
  ft->sox_errno = SOX_SUCCESS;
  return SOX_SUCCESS;
}

int lsx_skipbytes(sox_format_t ft, size_t n)
{
  if (!n)
    return SOX_SUCCESS;
  if (ft->seekable && ft->fp && fseeko(ft->fp, (off_t)n, SEEK_CUR) >= 0) {
    ft->tell_off = ftello(ft->fp);
    ft->tell_off_valid = sox_true;
    return SOX_SUCCESS;
  }
  return discard_bytes(ft, (uint64_t)n);
}

int lsx_padbytes(sox_format_t ft, size_t n)
{
  static char const zeros[1024];

  while (n) {
    size_t want = n > sizeof(zeros) ? sizeof(zeros) : n;
    if (lsx_writebuf(ft, zeros, want) != want)
      return SOX_EOF;
    n -= want;
  }
  return SOX_SUCCESS;
}

uint64_t lsx_filelength(sox_format_t ft)
{
  struct stat st;

  if (!ft->fp || fstat(fileno(ft->fp), &st) < 0 || !S_ISREG(st.st_mode))
    return 0;
  return (uint64_t)st.st_size;
}

/*---------------------------- scalar accessors -----------------------------*/

int lsx_readb(sox_format_t ft, unsigned char *ub)
{
  return lsx_readbuf(ft, ub, (size_t)1) == 1 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_writeb(sox_format_t ft, unsigned ub)
{
  unsigned char b = (unsigned char)ub;
  return lsx_writebuf(ft, &b, (size_t)1) == 1 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_readw(sox_format_t ft, uint16_t *uw)
{
  unsigned char b[2];

  if (lsx_readbuf(ft, b, (size_t)2) != 2)
    return SOX_EOF;
  *uw = reversing(ft) ? (uint16_t)(((uint16_t)b[0] << 8) | b[1])
                      : (uint16_t)(((uint16_t)b[1] << 8) | b[0]);
  return SOX_SUCCESS;
}

int lsx_writew(sox_format_t ft, unsigned uw)
{
  unsigned char b[2];

  if (reversing(ft)) {
    b[0] = (unsigned char)(uw >> 8);
    b[1] = (unsigned char)uw;
  } else {
    b[0] = (unsigned char)uw;
    b[1] = (unsigned char)(uw >> 8);
  }
  return lsx_writebuf(ft, b, (size_t)2) == 2 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_read3(sox_format_t ft, uint32_t *u3)
{
  unsigned char b[3];

  if (lsx_readbuf(ft, b, (size_t)3) != 3)
    return SOX_EOF;
  *u3 = reversing(ft)
      ? ((uint32_t)b[0] << 16) | ((uint32_t)b[1] << 8) | b[2]
      : ((uint32_t)b[2] << 16) | ((uint32_t)b[1] << 8) | b[0];
  return SOX_SUCCESS;
}

int lsx_write3(sox_format_t ft, uint32_t u3)
{
  unsigned char b[3];

  if (reversing(ft)) {
    b[0] = (unsigned char)(u3 >> 16);
    b[1] = (unsigned char)(u3 >> 8);
    b[2] = (unsigned char)u3;
  } else {
    b[0] = (unsigned char)u3;
    b[1] = (unsigned char)(u3 >> 8);
    b[2] = (unsigned char)(u3 >> 16);
  }
  return lsx_writebuf(ft, b, (size_t)3) == 3 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_readdw(sox_format_t ft, uint32_t *udw)
{
  uint32_t v;

  if (lsx_readbuf(ft, &v, (size_t)4) != 4)
    return SOX_EOF;
  *udw = reversing(ft) ? swap32(v) : v;
  return SOX_SUCCESS;
}

int lsx_writedw(sox_format_t ft, uint32_t udw)
{
  uint32_t v = reversing(ft) ? swap32(udw) : udw;
  return lsx_writebuf(ft, &v, (size_t)4) == 4 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_readqw(sox_format_t ft, uint64_t *uqw)
{
  uint64_t v;

  if (lsx_readbuf(ft, &v, (size_t)8) != 8)
    return SOX_EOF;
  *uqw = reversing(ft) ? swap64(v) : v;
  return SOX_SUCCESS;
}

int lsx_writeqw(sox_format_t ft, uint64_t uqw)
{
  uint64_t v = reversing(ft) ? swap64(uqw) : uqw;
  return lsx_writebuf(ft, &v, (size_t)8) == 8 ? SOX_SUCCESS : SOX_EOF;
}

int lsx_readf(sox_format_t ft, float *f)
{
  uint32_t v;

  if (lsx_readdw(ft, &v) == SOX_EOF)
    return SOX_EOF;
  memcpy(f, &v, sizeof(*f) < sizeof(v) ? sizeof(*f) : sizeof(v));
  return SOX_SUCCESS;
}

int lsx_writef(sox_format_t ft, double f)
{
  float t = (float)f;
  uint32_t v;

  memcpy(&v, &t, sizeof(v));
  return lsx_writedw(ft, v);
}

int lsx_readdf(sox_format_t ft, double *d)
{
  uint64_t v;

  if (lsx_readqw(ft, &v) == SOX_EOF)
    return SOX_EOF;
  memcpy(d, &v, sizeof(*d) < sizeof(v) ? sizeof(*d) : sizeof(v));
  return SOX_SUCCESS;
}

int lsx_writedf(sox_format_t ft, double d)
{
  uint64_t v;

  memcpy(&v, &d, sizeof(v));
  return lsx_writeqw(ft, v);
}

/*--------------------------------- strings ---------------------------------*/

/* Read at most `len' characters, stopping early at a NUL or a newline (which
 * is consumed but not stored).  A terminating NUL is always appended, so the
 * buffer must have room for len + 1 characters.  SOX_EOF is returned if the
 * file ended before a terminator was seen; whatever was read is still
 * NUL-terminated. */
int lsx_reads(sox_format_t ft, char *c, size_t len)
{
  size_t n = 0;
  int result = SOX_SUCCESS;

  while (n < len) {
    unsigned char in;
    if (lsx_readbuf(ft, &in, (size_t)1) != 1) {
      result = SOX_EOF;
      break;
    }
    if (in == '\0' || in == '\n')
      break;
    c[n++] = (char)in;
  }
  c[n] = '\0';
  return result;
}

/* Write the string, excluding its terminating NUL. */
int lsx_writes(sox_format_t ft, char const *c)
{
  size_t len = strlen(c);
  return lsx_writebuf(ft, c, len) == len ? SOX_SUCCESS : SOX_EOF;
}

/* Read exactly `len' bytes; no NUL is appended. */
int lsx_readchars(sox_format_t ft, char *chars, size_t len)
{
  return lsx_readbuf(ft, chars, len) == len ? SOX_SUCCESS : SOX_EOF;
}

/*------------------------------ array accessors ----------------------------*/

static size_t read_items(sox_format_t ft, void *buf, size_t size, size_t len)
{
  size_t got = lsx_readbuf(ft, buf, len * size) / size;

  if (got && reversing(ft))
    reverse_items(buf, size, got);
  return got;
}

static size_t write_items(sox_format_t ft, void const *buf, size_t size,
                          size_t len)
{
  char tmp[4096];
  size_t per = sizeof(tmp) / size, done = 0;
  char const *p = buf;

  if (!reversing(ft))
    return lsx_writebuf(ft, buf, len * size) / size;

  while (done < len) {
    size_t want = len - done < per ? len - done : per;
    size_t put;
    memcpy(tmp, p + done * size, want * size);
    reverse_items(tmp, size, want);
    put = lsx_writebuf(ft, tmp, want * size) / size;
    done += put;
    if (put != want)
      break;
  }
  return done;
}

size_t lsx_read_b_buf(sox_format_t ft, uint8_t *buf, size_t len)
{
  return lsx_readbuf(ft, buf, len);
}

size_t lsx_write_b_buf(sox_format_t ft, uint8_t const *buf, size_t len)
{
  return lsx_writebuf(ft, buf, len);
}

size_t lsx_read_w_buf(sox_format_t ft, uint16_t *buf, size_t len)
{
  return read_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_write_w_buf(sox_format_t ft, uint16_t const *buf, size_t len)
{
  return write_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_read_3_buf(sox_format_t ft, uint32_t *buf, size_t len)
{
  unsigned char tmp[3 * 512];
  size_t per = sizeof(tmp) / 3, done = 0;

  while (done < len) {
    size_t want = len - done < per ? len - done : per;
    size_t got = lsx_readbuf(ft, tmp, want * 3) / 3, i;
    for (i = 0; i < got; ++i) {
      unsigned char *b = tmp + i * 3;
      buf[done + i] = reversing(ft)
          ? ((uint32_t)b[0] << 16) | ((uint32_t)b[1] << 8) | b[2]
          : ((uint32_t)b[2] << 16) | ((uint32_t)b[1] << 8) | b[0];
    }
    done += got;
    if (got != want)
      break;
  }
  return done;
}

size_t lsx_write_3_buf(sox_format_t ft, uint32_t const *buf, size_t len)
{
  unsigned char tmp[3 * 512];
  size_t per = sizeof(tmp) / 3, done = 0;

  while (done < len) {
    size_t want = len - done < per ? len - done : per, put, i;
    for (i = 0; i < want; ++i) {
      unsigned char *b = tmp + i * 3;
      uint32_t v = buf[done + i];
      if (reversing(ft)) {
        b[0] = (unsigned char)(v >> 16);
        b[1] = (unsigned char)(v >> 8);
        b[2] = (unsigned char)v;
      } else {
        b[0] = (unsigned char)v;
        b[1] = (unsigned char)(v >> 8);
        b[2] = (unsigned char)(v >> 16);
      }
    }
    put = lsx_writebuf(ft, tmp, want * 3) / 3;
    done += put;
    if (put != want)
      break;
  }
  return done;
}

size_t lsx_read_dw_buf(sox_format_t ft, uint32_t *buf, size_t len)
{
  return read_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_write_dw_buf(sox_format_t ft, uint32_t const *buf, size_t len)
{
  return write_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_read_qw_buf(sox_format_t ft, uint64_t *buf, size_t len)
{
  return read_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_write_qw_buf(sox_format_t ft, uint64_t const *buf, size_t len)
{
  return write_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_read_f_buf(sox_format_t ft, float *buf, size_t len)
{
  return read_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_write_f_buf(sox_format_t ft, float const *buf, size_t len)
{
  return write_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_read_df_buf(sox_format_t ft, double *buf, size_t len)
{
  return read_items(ft, buf, sizeof(*buf), len);
}

size_t lsx_write_df_buf(sox_format_t ft, double const *buf, size_t len)
{
  return write_items(ft, buf, sizeof(*buf), len);
}

/*--------------------------------- seeking ---------------------------------*/

/* Seek to the frame containing sample `to_sample' (a count of samples over
 * all channels) in data that starts at `byte_offset'. */
int lsx_offset_seek(sox_format_t ft, off_t byte_offset, uint64_t to_sample)
{
  double wide_sample, to_bytes;
  off_t to;

  if (ft->signal.channels)
    to_sample -= to_sample % ft->signal.channels;
  wide_sample = (double)to_sample;
  to_bytes = wide_sample * ft->encoding.bits_per_sample / 8;
  to = (off_t)to_bytes;
  if ((double)to != to_bytes)          /* overflowed */
    return SOX_EOF;
  return lsx_seeki(ft, byte_offset + to, SEEK_SET);
}

/*------------------------- textual field extraction ------------------------*/

static int rf_getc(sox_format_t ft)
{
  unsigned char b;
  return lsx_readbuf(ft, &b, (size_t)1) == 1 ? (int)b : -1;
}

static void rf_ungetc(sox_format_t ft, int c)
{
  if (c >= 0)
    lsx_unreadb(ft, (unsigned)c);
}

static int rf_skip_space(sox_format_t ft)
{
  int c;
  do
    c = rf_getc(ft);
  while (c >= 0 && isspace(c));
  rf_ungetc(ft, c);
  return c;
}

static int digit_val(int c, int base)
{
  int v;
  if (isdigit(c)) v = c - '0';
  else if (isalpha(c)) v = tolower(c) - 'a' + 10;
  else return -1;
  return v < base ? v : -1;
}

/* Scan whitespace-separated fields from the file according to a scanf-like
 * spec; see ../notes/formats_i.md for the supported conversions.  *n (if not
 * NULL) receives the number of fields assigned; the return value is
 * SOX_SUCCESS only if every directive in the spec was satisfied. */
int lsx_read_fields(sox_format_t ft, size_t *n, char const *spec, ...)
{
  va_list ap;
  size_t assigned = 0;
  int ok = 1;

  va_start(ap, spec);
  while (*spec && ok) {
    if (isspace((unsigned char)*spec)) {
      while (isspace((unsigned char)*spec))
        ++spec;
      rf_skip_space(ft);
      continue;
    }
    if (*spec != '%') {
      int c = rf_getc(ft);
      if (c != (unsigned char)*spec) {
        rf_ungetc(ft, c);
        ok = 0;
        break;
      }
      ++spec;
      continue;
    }

    ++spec;                                  /* past the '%' */
    {
      int suppress = 0, longs = 0, shorts = 0;
      size_t width = 0;
      int conv;

      if (*spec == '*') { suppress = 1; ++spec; }
      while (isdigit((unsigned char)*spec))
        width = width * 10 + (size_t)(*spec++ - '0');
      for (;;) {
        if (*spec == 'l' || *spec == 'L' || *spec == 'q' || *spec == 'j' ||
            *spec == 'z') { ++longs; ++spec; }
        else if (*spec == 'h') { ++shorts; ++spec; }
        else break;
      }
      conv = *spec ? *spec++ : 0;

      switch (conv) {
      case '%': {
        int c = rf_getc(ft);
        if (c != '%') { rf_ungetc(ft, c); ok = 0; }
        break;
      }
      case 'c': {
        size_t want = width ? width : 1, got = 0;
        char *p = suppress ? NULL : va_arg(ap, char *);
        while (got < want) {
          int c = rf_getc(ft);
          if (c < 0) break;
          if (p) p[got] = (char)c;
          ++got;
        }
        if (got != want) ok = 0;
        else if (p) ++assigned;
        break;
      }
      case 's': {
        char *p = suppress ? NULL : va_arg(ap, char *);
        size_t got = 0;
        int c;
        rf_skip_space(ft);
        for (;;) {
          c = rf_getc(ft);
          if (c < 0 || isspace(c)) { rf_ungetc(ft, c); break; }
          if (width && got >= width) { rf_ungetc(ft, c); break; }
          if (p) p[got] = (char)c;
          ++got;
        }
        if (p) p[got] = '\0';
        if (!got) ok = 0;
        else if (p) ++assigned;
        break;
      }
      case 'd': case 'i': case 'u': case 'x': case 'X': case 'o': {
        int base = conv == 'x' || conv == 'X' ? 16 : conv == 'o' ? 8 : 10;
        int neg = 0, ndig = 0, c;
        uint64_t v = 0;
        size_t used = 0;

        rf_skip_space(ft);
        c = rf_getc(ft);
        if (c == '+' || c == '-') {
          neg = c == '-';
          ++used;
          c = rf_getc(ft);
        }
        while (c >= 0 && (!width || used < width) && digit_val(c, base) >= 0) {
          v = v * (uint64_t)base + (uint64_t)digit_val(c, base);
          ++ndig; ++used;
          c = rf_getc(ft);
        }
        rf_ungetc(ft, c);
        if (!ndig) { ok = 0; break; }
        if (neg)
          v = (uint64_t)-(int64_t)v;
        if (!suppress) {
          if (longs >= 2)      *va_arg(ap, long long *) = (long long)v;
          else if (longs == 1) *va_arg(ap, long *) = (long)v;
          else if (shorts >= 2)*va_arg(ap, signed char *) = (signed char)v;
          else if (shorts == 1)*va_arg(ap, short *) = (short)v;
          else                 *va_arg(ap, int *) = (int)v;
          ++assigned;
        }
        break;
      }
      case 'f': case 'e': case 'E': case 'g': case 'G': {
        char buf[80];
        size_t got = 0;
        int c, seen_digit = 0, seen_dot = 0, seen_exp = 0;
        double d;

        rf_skip_space(ft);
        for (;;) {
          c = rf_getc(ft);
          if (c < 0) break;
          if (width && got >= width) { rf_ungetc(ft, c); break; }
          if (got + 1 >= sizeof(buf)) { rf_ungetc(ft, c); break; }
          if (isdigit(c)) { seen_digit = 1; }
          else if ((c == '+' || c == '-') &&
                   (got == 0 || buf[got - 1] == 'e' || buf[got - 1] == 'E')) ;
          else if (c == '.' && !seen_dot && !seen_exp) seen_dot = 1;
          else if ((c == 'e' || c == 'E') && seen_digit && !seen_exp)
            seen_exp = 1;
          else { rf_ungetc(ft, c); break; }
          buf[got++] = (char)c;
        }
        buf[got] = '\0';
        if (!seen_digit) { ok = 0; break; }
        d = strtod(buf, NULL);
        if (!suppress) {
          if (longs) *va_arg(ap, double *) = d;
          else       *va_arg(ap, float *) = (float)d;
          ++assigned;
        }
        break;
      }
      default:
        ok = 0;
        break;
      }
    }
  }
  va_end(ap);
  if (n)
    *n = assigned;
  return ok ? SOX_SUCCESS : SOX_EOF;
}

/*--------------------------- header vs. user options -----------------------*/

/* Called by a format's startread once it has decoded its header.  Values that
 * the user has overridden on the command line win, with a warning; everything
 * else is taken from the header.  With --ignore-length the length implied by
 * the file size is used instead of the one in the header. */
int lsx_check_read_params(sox_format_t ft, unsigned channels, double rate,
                          sox_encoding_t encoding, unsigned bits_per_sample,
                          uint64_t num_samples, sox_bool check_length)
{
  sox_bool ignore_length = ft->ignore_length ||
      ft->signal.length == SOX_IGNORE_LENGTH;
  uint64_t calculated = 0;
  sox_bool have_calculated = sox_false;

  if (channels && ft->signal.channels && ft->signal.channels != channels)
    lsx_warn("`%s': overriding number of channels", ft->filename);
  else ft->signal.channels = channels;

  if (rate && ft->signal.rate && ft->signal.rate != rate)
    lsx_warn("`%s': overriding sample rate", ft->filename);
  else ft->signal.rate = rate;

  if (encoding && ft->encoding.encoding && ft->encoding.encoding != encoding)
    lsx_warn("`%s': overriding encoding type", ft->filename);
  else ft->encoding.encoding = encoding;

  if (bits_per_sample && ft->encoding.bits_per_sample &&
      ft->encoding.bits_per_sample != bits_per_sample)
    lsx_warn("`%s': overriding encoding size", ft->filename);
  else ft->encoding.bits_per_sample = bits_per_sample;

  if (!ft->signal.precision)
    ft->signal.precision =
        lsx_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);

  if (ft->seekable && bits_per_sample) {
    uint64_t length = lsx_filelength(ft);
    off_t here = lsx_tell(ft);
    if (here >= 0 && length >= (uint64_t)here) {
      calculated = (length - (uint64_t)here) * 8 / bits_per_sample;
      have_calculated = sox_true;
    }
  }

  if (ignore_length)
    ft->signal.length = have_calculated ? calculated : SOX_UNSPEC;
  else {
    if (num_samples && num_samples != SOX_UNKNOWN_LEN)
      ft->signal.length = num_samples;
    if (check_length && have_calculated &&
        num_samples && num_samples != SOX_UNKNOWN_LEN &&
        num_samples != calculated)
      lsx_warn("`%s': file header gives the total number of samples as %llu "
               "but file length indicates the number is in fact %llu",
               ft->filename, (unsigned long long)num_samples,
               (unsigned long long)calculated);
  }
  return SOX_SUCCESS;
}

