uint64_t lsx_filelength(sox_format_t ft)
{
  struct stat st;

  if (!ft->fp)
    return 0;
  if (ft->mode == 'w')
    fflush(ft->fp);
  if (fstat(fileno(ft->fp), &st) < 0 || !S_ISREG(st.st_mode))
    return 0;
  return (uint64_t)st.st_size;
}

